mapper.select:
		SELECT *
  	FROM (
    		SELECT ROWNUM rnum, t.*
    		FROM (
      		SELECT *
      		FROM REPORTS
      		WHERE DESCRIPTION LIKE '%' || #{search} || '%'
      		ORDER BY CREATED_AT DESC
    		) t
    		WHERE ROWNUM <= #{endRow}
  	)
  	WHERE rnum >= #{startRow}

mapper.update:
UPDATE REPORTS
SET STATUS = #{status}
WHERE DEFECT_ID = #{id}
